    "similar_words": "පත්ති, යුත්ති, වුත්ති, කිත්ති, මුත්ති, තිත්ති, ඛන්ති, කන්ති, සන්ති, තන්ති, සිද්ධි, සුද්ධි, ඉද්ධි, වුද්ධි, බුද්ධි, බොධි, භූමි, ජාති, පීති, සූති, නන්දි, සන්ධි, සාණි, කොටි, දිට්ඨි, වුඩ්ඪි, තුට්ඨි, යට්ඨි, පාළි, ආළි, නාළි, කෙළි, සති, මති, ගති, චුති, ධිති, යුවති, විකති, රති, රුචි, රස්මි, අසනි, වසනි, ඔසධි, අඞ්ගුලි, ධූලි, දුන්දුභි, දොණි, අටවි, ඡවි ආදිය",
    "notes": [
      "‘රත්‍යො, රත්‍යා, රත්‍යං’ ආදියෙහි ‘පසඤ්ඤස්ස ච’ (185) සූත්‍රයෙන් ඉ හට යකාරය වූ පසු ත්ත්‍ය යන ව්‍යඤ්ජන තුනෙහි සරූප ව්‍යඤ්ජන දෙකින් පළමුවැන්න ලොප් වේ (නිරුත්තිදීපනී). ‘යවතං තලන…’ සූත්‍රයෙන් චකාරත්වය නොවේ — අනුවෘත්ත වා ශබ්දය හෙයිනි (සන්නය).",
      "‘අමා පතො ස්මිංස්මානං වා’ (184) හි වා ශබ්දය ව්‍යවස්ථිත විභාෂා අර්ථයි; එබැවින් උවණ්ණාන්ත (යාගු ආදී) ශබ්දයන් කෙරෙන් අං/ආ ආදේශ නොවේ; ඉවණ්ණාන්ත ශබ්දයන් කෙරෙන් ද ප්‍රයෝගානුරූපව පමණි.",
      "බොධි ශබ්දය වෘක්‍ෂ වාචී වූ කල්හි ද, සන්ධි ශබ්දය අස්ථි සන්ධි ආදි වාචී වූ කල්හි ද පුල්ලිඞ්ග වේ (සන්නය)."
    ],
