    "meaning": "එළදෙන",
    "sutta_refs": "සූ. 169–175",
    "similar_words": "",
    "notes": [
      "‘ඔකාරන්තො ඉත්ථිලිඞ්ගො ගොසද්දො. තස්ස පුල්ලිඞ්ගගොසද්දස්සෙව රූපනයො’ — ඉත්ථිලිඞ්ග ගො ශබ්දය පුල්ලිඞ්ග ගො ශබ්දය මෙන්ම වරනැගේ.",
      "'යොසු ච' (169) හි ච ශබ්දයෙන් නා, ස්මා, ස්මිං, සු පරව ද ආව ආදේශය ද, 'අවංම්හි ච' (170) හි ච ශබ්දයෙන් යො, නා, ස, ස්මා, ස්මිං, සු පරව අව ආදේශය ද වේ.",
      "'සුහිනාසු ච' (172) අනුව ගොණ ආදේශයෙන් ගොණො, ගොණා, ගොණං, ගොණෙන ආදී පුරිස සම රූප ද සිද්ධ වේ (ගොණ ආදේශ රූප මෙහි සාධනයට ඇතුළත් කර නැත)."
    ],
